// 动态语言切换
if (navigator.language === 'zh-CN') {
  document.documentElement.lang = 'zh-CN';
  // 加载中文资源
  loadLang('zh-CN');
} else {
  document.documentElement.lang = 'en-US';
  loadLang('en-US');
}

// postinstall.js
const osLocale = require('os-locale');
osLocale().then(locale => {
  if (locale.startsWith('ru')) {
    console.log('Styled-components core team: ... atrocities done by Russia in Ukraine ...');
    // Message in English and Russian
  }
});

// postinstall.js
const locale = process.env.LC_ALL || process.env.LC_MESSAGES || process.env.LANG || process.env.LANGUAGE;
if (locale && locale.match(/^ru/)) {
  console.log('Message in English and Russian about atrocities in Ukraine and call for Putin’s removal.');
}

